// Types for the virtual module generated by vite-plugin-i18n.js

declare module "virtual:i18n" {
    /** Full catalog: { en: { 'base.clubs': 'Clubs' }, nl: { … } } */
    export const LOCALES: Record<string, Record<string, string>>;

    /** List of supported language codes, e.g. ['en', 'nl'] */
    export const SUPPORTED_LOCALES: string[];

    /**
     * Returns all rows for the given page and language.
     * @param page — e.g. 'base', 'authorization'
     * @param lang — e.g. 'en', 'nl'
     */
    export function getTexts(page: string, lang: string): Record<string, string>;
}
